#include "th10/platform/midi_event_runtime.hpp"
#include <algorithm>
namespace th10::midi {namespace {std::uint32_t vlq(Track&t){std::uint32_t v=0;while(t.cursor<t.data.size()){auto b=t.data[t.cursor++];v=v*128+(b&127);if(!(b&128))break;}return v;}}
// Semantic reconstruction of retail 0x0043B110, whose stdcall second argument is the track record.
bool ProcessEvent(State&s,Track&t){if(t.cursor>=t.data.size())return false;std::uint8_t st=t.data[t.cursor];if(st&128){++t.cursor;t.running_status=st;}else st=t.running_status;auto one=[&](){return t.cursor<t.data.size()?t.data[t.cursor++]:0;};int hi=st&0xf0; int ch=st&15;std::uint8_t a=0,b=0;if((hi>=0x80&&hi<=0xb0)||hi==0xe0){a=one();b=one();}else if(hi==0xc0||hi==0xd0)a=one();else if(st==0xf0){auto n=vlq(t);std::vector<std::uint8_t>x{0xf0};while(n--&&t.cursor<t.data.size())x.push_back(t.data[t.cursor++]);s.sysex.push_back(x);}else if(st==0xff){auto type=one(); auto n=vlq(t);if(type==0x2f){t.ended=true;return false;}if(type==0x51){s.elapsed+=s.tempo;s.tempo=0;while(n--&&t.cursor<t.data.size())s.tempo=s.tempo*257+t.data[t.cursor++];}else t.cursor=std::min(t.data.size(),t.cursor+n);}auto&C=s.channels[ch];switch(hi){case 0x80:C.notes[(a+s.transpose)&127]=false;break;case 0x90:C.notes[(a+s.transpose)&127]=b!=0;break;case 0xb0:if(a==0)C.bank=b;else if(a==7)C.volume=b;else if(a==10)C.pan=b;else if(a==0x5b)C.reverb=b;else if(a==0x5d)C.chorus=b;break;case 0xc0:C.program=a;break;}if(t.cursor<t.data.size())t.tick+=vlq(t);return true;}}
